    identifier_key: str | None

    def get_olids(self, identifier: str) -> list[str]:
        return web.ctx.site.things(
            {"type": "/type/edition", self.db_selector: identifier}
        )

    @property
    def editions_query(self):
        return {f"{self.db_selector}~": "*"}

